#!/usr/bin/env python3
"""
CSV column summary CLI with optional row filtering.

Usage:
    python csv_summary.py <csv_file> [--filter column_name=regex]
"""

from __future__ import annotations

import argparse
import csv
import math
import re
import sys
from pathlib import Path
from statistics import mean, stdev
from typing import Dict, List, Tuple, Union


def _is_int(value: str) -> bool:
    """Return True if the string represents an integer."""
    try:
        int(value)
        return True
    except ValueError:
        return False


def _is_float(value: str) -> bool:
    """Return True if the string represents a float."""
    try:
        float(value)
        return True
    except ValueError:
        return False


def _compute_stats(values: List[float]) -> Tuple[float, Union[float, None]]:
    """Return mean and standard deviation for a list of floats."""
    if not values:
        return (float("nan"), None)
    m = mean(values)
    if len(values) < 2:
        return (m, None)
    try:
        s = stdev(values)
    except Exception:
        s = None
    return (m, s)


def _summarize_column(name: str, raw_values: List[str]) -> Dict[str, Union[str, int, float, None]]:
    """Return a summary dict for a single column."""
    nulls = sum(1 for v in raw_values if v.strip() == "")
    non_nulls = [v for v in raw_values if v.strip() != ""]

    # Determine dtype
    if all(_is_int(v) for v in non_nulls):
        dtype = "int"
        numeric_values = [int(v) for v in non_nulls]
    elif all(_is_float(v) for v in non_nulls):
        dtype = "float"
        numeric_values = [float(v) for v in non_nulls]
    else:
        dtype = "string"
        numeric_values = []

    if numeric_values:
        m, s = _compute_stats(numeric_values)
    else:
        m, s = (None, None)

    return {
        "name": name,
        "dtype": dtype,
        "nulls": nulls,
        "mean": m,
        "std": s,
    }


def _parse_filter(filter_str: str) -> Tuple[str, re.Pattern]:
    """Parse a filter string of the form 'column=regex'."""
    if "=" not in filter_str:
        raise ValueError("Filter must be in the form 'column=regex'")
    col, pattern = filter_str.split("=", 1)
    if not col:
        raise ValueError("Filter column name cannot be empty")
    try:
        regex = re.compile(pattern)
    except re.error as exc:
        raise ValueError(f"Invalid regex '{pattern}': {exc}") from exc
    return col, regex


def run() -> None:
    """Entry point for the CLI."""
    parser = argparse.ArgumentParser(description="Print a summary of each CSV column.")
    parser.add_argument("csv_file", type=Path, help="Path to the CSV file.")
    parser.add_argument(
        "--filter",
        type=str,
        help="Filter rows: 'column_name=regex'. Only rows where the column matches the regex are kept.",
    )
    args = parser.parse_args()

    csv_path = args.csv_file
    if not csv_path.is_file():
        parser.error(f"File not found: {csv_path}")

    # Read all rows first
    with csv_path.open(newline="") as f:
        reader = csv.DictReader(f)
        fieldnames = reader.fieldnames
        if fieldnames is None:
            print("No columns found.", file=sys.stderr)
            sys.exit(1)

        rows: List[Dict[str, str]] = list(reader)

    # Apply filter if requested
    if args.filter:
        try:
            filter_col, regex = _parse_filter(args.filter)
        except ValueError as exc:
            print(f"Error parsing filter: {exc}", file=sys.stderr)
            sys.exit(1)

        if filter_col not in fieldnames:
            print(f"Filter column '{filter_col}' not found in CSV.", file=sys.stderr)
            sys.exit(1)

        rows = [row for row in rows if regex.search(row.get(filter_col, ""))]

    # Collect raw values per column
    columns: Dict[str, List[str]] = {name: [] for name in fieldnames}
    for row in rows:
        for name in fieldnames:
            columns[name].append(row.get(name, ""))

    # Print header
    header = f"{'Column':<20} {'Dtype':<10} {'Nulls':<6} {'Mean':<10} {'Std':<10}"
    print(header)
    print("-" * len(header))

    for name in fieldnames:
        summary = _summarize_column(name, columns[name])
        mean_str = f"{summary['mean']:.4f}" if isinstance(summary["mean"], float) else "N/A"
        std_str = f"{summary['std']:.4f}" if isinstance(summary["std"], float) else "N/A"
        print(f"{summary['name']:<20} {summary['dtype']:<10} {summary['nulls']:<6} {mean_str:<10} {std_str:<10}")


if __name__ == "__main__":
    run()
```

**Example**

```bash
$ python csv_summary.py data.csv --filter age=^[3-5]
```

This keeps only rows where the `age` column starts with 3, 4, or 5 before summarising.  

